-- Run with Supabase migrations as postgres. No fabricated events or ratings.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to anon, authenticated;

create table public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 display_name text not null default 'Runner' check(length(display_name) between 1 and 80),
 suspended boolean not null default false, created_at timestamptz not null default now()
);
create table public.user_roles (user_id uuid primary key references public.profiles(id) on delete cascade, role text not null check(role in ('user','admin')) default 'user');
create table public.divisions (id smallint primary key, name text not null unique);
insert into public.divisions values (1,'Dhaka'),(2,'Chattogram'),(3,'Rajshahi'),(4,'Khulna'),(5,'Barishal'),(6,'Sylhet'),(7,'Rangpur'),(8,'Mymensingh');
create table public.districts (id smallint primary key, division_id smallint not null references public.divisions, name text not null, unique(id,division_id), unique(division_id,name));
insert into public.districts values
