(14,2,'Bandarban'),(15,2,'Brahmanbaria'),(16,2,'Chandpur'),(17,2,'Chattogram'),(18,2,'Cumilla'),(19,2,'Cox''s Bazar'),(20,2,'Feni'),(21,2,'Khagrachhari'),(22,2,'Lakshmipur'),(23,2,'Noakhali'),(24,2,'Rangamati'),
(25,3,'Bogura'),(26,3,'Joypurhat'),(27,3,'Naogaon'),(28,3,'Natore'),(29,3,'Chapainawabganj'),(30,3,'Pabna'),(31,3,'Rajshahi'),(32,3,'Sirajganj'),
(33,4,'Bagerhat'),(34,4,'Chuadanga'),(35,4,'Jashore'),(36,4,'Jhenaidah'),(37,4,'Khulna'),(38,4,'Kushtia'),(39,4,'Magura'),(40,4,'Meherpur'),(41,4,'Narail'),(42,4,'Satkhira'),
(43,5,'Barguna'),(44,5,'Barishal'),(45,5,'Bhola'),(46,5,'Jhalokati'),(47,5,'Patuakhali'),(48,5,'Pirojpur'),
