(53,7,'Dinajpur'),(54,7,'Gaibandha'),(55,7,'Kurigram'),(56,7,'Lalmonirhat'),(57,7,'Nilphamari'),(58,7,'Panchagarh'),(59,7,'Rangpur'),(60,7,'Thakurgaon'),
(61,8,'Jamalpur'),(62,8,'Mymensingh'),(63,8,'Netrokona'),(64,8,'Sherpur');
create table public.categories(id smallint generated by default as identity primary key, name text not null unique check(length(name) between 1 and 60));
insert into public.categories(name) values ('Running'),('Cycling'),('Outdoor'),('Community'),('Culture'),('Technology'),('Other');
create table public.organizers (
 id uuid primary key default gen_random_uuid(), owner_id uuid not null unique references public.profiles,
 name text not null check(length(name) between 2 and 100), description text not null default '' check(length(description)<=3000),
 contact text not null check(length(contact) between 3 and 200), website text check(website is null or website ~ '^https://[^/[:space:]]+'),
 social_url text check(social_url is null or social_url ~ '^https://[^/[:space:]]+'), logo_path text,
 approval text not null default 'pending' check(approval in ('pending','approved','rejected')),
 verified boolean not null default false, suspended boolean not null default false, created_at timestamptz not null default now()
);
create table public.organizer_verifications (
 id uuid primary key default gen_random_uuid(), organizer_id uuid not null references public.organizers on delete cascade,
 user_id uuid not null references public.profiles, evidence text not null check(length(evidence) between 10 and 3000),
 status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now()
);
create unique index one_pending_verification on public.organizer_verifications(organizer_id) where status='pending';
create table public.events (
 id uuid primary key default gen_random_uuid(), organizer_id uuid not null references public.organizers,
 name text not null check(length(name) between 3 and 120), description text not null check(length(description) between 10 and 6000),
 category_id smallint not null references public.categories, division_id smallint not null references public.divisions,
 district_id smallint not null, foreign key(district_id,division_id) references public.districts(id,division_id),
 starts_at timestamptz not null, ends_at timestamptz not null, registration_deadline timestamptz not null,
 venue text not null check(length(venue) between 2 and 180), address text not null check(length(address) between 3 and 500),
 map_url text check(map_url is null or map_url ~ '^https://[^/[:space:]]+'), cover_path text,
 contact text not null check(length(contact) between 3 and 200), price numeric(10,2) not null default 0 check(price>=0),
 registration_url text check(registration_url is null or registration_url ~ '^https://[^/[:space:]]+'),
 approval text not null default 'pending' check(approval in ('pending','approved','rejected')), cancelled boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(ends_at>starts_at), check(registration_deadline<=starts_at), check(price=0 or registration_url is not null)
);
create index event_calendar on public.events(starts_at,division_id) where approval='approved';
create index event_org on public.events(organizer_id);
create index event_category_district on public.events(category_id,district_id,starts_at);
create table public.event_registrations (
 id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade,
 user_id uuid not null references public.profiles on delete cascade,
 status text not null check(status in ('interested','registered','attended','cancelled')),
 created_at timestamptz not null default now(), unique(event_id,user_id)
);
create table public.saved_events(user_id uuid not null references public.profiles on delete cascade, event_id uuid not null references public.events on delete cascade, created_at timestamptz not null default now(), primary key(user_id,event_id));
-- Rating and written review are one row: one event experience, one score.
create table public.reviews (
 id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events,
 user_id uuid not null references public.profiles, organizer_id uuid not null references public.organizers,
 score smallint not null check(score between 1 and 10), body text not null check(length(body) between 10 and 2000),
 author_name text not null, verified_attendance boolean not null default true,
 moderation text not null default 'pending' check(moderation in ('pending','approved','rejected')),
 reply text check(length(reply)<=2000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(event_id,user_id)
);
create index reviews_org on public.reviews(organizer_id,moderation);
create table public.reports(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, target_type text not null check(target_type in ('review','organizer','event','user')), target_id uuid not null, reason text not null check(length(reason) between 10 and 2000), status text not null default 'open' check(status in ('open','resolved','dismissed')), created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, event_id uuid references public.events on delete cascade, title text not null, body text not null, read_at timestamptz, created_at timestamptz not null default now());
create index notifications_owner on public.notifications(user_id,created_at desc);
create table public.push_tokens(user_id uuid not null references public.profiles on delete cascade, token text not null check(token ~ '^(ExponentPushToken|ExpoPushToken)\['), primary key(user_id,token));
create table private.push_outbox(id uuid primary key default gen_random_uuid(), notification_id uuid not null unique references public.notifications on delete cascade, claimed_at timestamptz, delivered_at timestamptz, attempts integer not null default 0, error text);
create table public.admin_audit_logs(id bigint generated always as identity primary key, admin_id uuid references public.profiles, action text not null, target_id uuid, created_at timestamptz not null default now());
create table private.rate_limits(user_id uuid not null, action text not null, bucket timestamptz not null, count integer not null default 1, primary key(user_id,action,bucket));

create function private.active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and not suspended) $$;
create function private.admin() returns boolean language sql stable security definer set search_path='' as $$ select private.active() and coalesce(auth.jwt()->>'aal','')='aal2' and exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin') $$;
create function private.owns(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.active() and exists(select 1 from public.organizers where id=org and owner_id=auth.uid() and not suspended) $$;
create function private.visible_org(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organizers o join public.profiles p on p.id=o.owner_id where o.id=org and o.approval='approved' and not o.suspended and not p.suspended) $$;
create function private.visible_event(eid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.events e where e.id=eid and e.approval='approved' and private.visible_org(e.organizer_id)) $$;
create function private.require_user() returns uuid language plpgsql security definer set search_path='' as $$ begin if not private.active() then raise exception 'Sign in with an active account' using errcode='42501'; end if; return auth.uid(); end $$;
create function private.limit_action(action_name text, maximum integer default 30) returns void language plpgsql security definer set search_path='' as $$ declare n integer; begin
 perform private.require_user();
 insert into private.rate_limits(user_id,action,bucket) values(auth.uid(),action_name,date_trunc('hour',now())) on conflict(user_id,action,bucket) do update set count=private.rate_limits.count+1 returning count into n;
 if n>maximum then raise exception 'Too many requests. Try again later.' using errcode='P0001'; end if;
 end $$;
create function private.on_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(nullif(trim(new.raw_user_meta_data->>'display_name'),''),'Runner'),80)); insert into public.user_roles(user_id) values(new.id); return new; end $$;
create trigger new_user after insert on auth.users for each row execute function private.on_new_user();

-- Read policies; writes use narrowly scoped RPCs, except private owner collections.
do $$ declare t text; begin foreach t in array array['profiles','user_roles','divisions','districts','categories','organizers','organizer_verifications','events','event_registrations','saved_events','reviews','reports','notifications','push_tokens','admin_audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); execute format('grant select on public.%I to authenticated',t); end loop; end $$;
grant select on public.divisions,public.districts,public.categories,public.organizers,public.events,public.reviews to anon;
create policy profile_self on public.profiles for select to authenticated using(id=auth.uid() or private.admin());
create policy role_self on public.user_roles for select to authenticated using(user_id=auth.uid() or private.admin());
create policy divisions_read on public.divisions for select using(true);
create policy districts_read on public.districts for select using(true);
create policy categories_read on public.categories for select using(true);
create policy org_read on public.organizers for select using(private.visible_org(id) or (owner_id=auth.uid() and private.active()) or private.admin());
create policy verification_read on public.organizer_verifications for select to authenticated using((user_id=auth.uid() and private.active()) or private.admin());
create policy events_read on public.events for select using(private.visible_event(id) or private.owns(organizer_id) or private.admin());
create policy registrations_read on public.event_registrations for select to authenticated using((user_id=auth.uid() and private.active()) or exists(select 1 from public.events e where e.id=event_id and private.owns(e.organizer_id)) or private.admin());
create policy reviews_read on public.reviews for select using((moderation='approved' and verified_attendance and private.visible_org(organizer_id)) or (user_id=auth.uid() and private.active()) or private.owns(organizer_id) or private.admin());
create policy reports_read on public.reports for select to authenticated using((user_id=auth.uid() and private.active()) or private.admin());
create policy saved_read on public.saved_events for select to authenticated using(user_id=auth.uid() and private.active());
create policy saved_add on public.saved_events for insert to authenticated with check(user_id=auth.uid() and private.active() and private.visible_event(event_id));
create policy saved_delete on public.saved_events for delete to authenticated using(user_id=auth.uid() and private.active());
grant insert,delete on public.saved_events to authenticated;
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid() and private.active());
create policy notifications_update on public.notifications for update to authenticated using(user_id=auth.uid() and private.active()) with check(user_id=auth.uid() and private.active());
grant update(read_at) on public.notifications to authenticated;
create policy tokens_own on public.push_tokens for all to authenticated using(user_id=auth.uid() and private.active()) with check(user_id=auth.uid() and private.active());
grant insert,update,delete on public.push_tokens to authenticated;
create policy audit_read on public.admin_audit_logs for select to authenticated using(private.admin());

create view public.organizer_ratings with (security_invoker=true) as select organizer_id,round(avg(score),1) as average_rating,count(*)::integer as review_count from public.reviews where moderation='approved' and verified_attendance group by organizer_id;
-- Only aggregate public popularity is exposed; user identities stay private.
create function public.event_popularity(eid uuid) returns bigint language sql stable security definer set search_path='' as $$ select count(*) from public.saved_events where event_id=eid and private.visible_event(eid) $$;
create view public.organizer_directory with (security_invoker=true) as select o.*,r.average_rating,coalesce(r.review_count,0) as review_count,(select count(*) from public.events e where e.organizer_id=o.id and e.approval='approved') as event_count from public.organizers o left join public.organizer_ratings r on r.organizer_id=o.id where private.visible_org(o.id);
create view public.event_directory with (security_invoker=true) as select e.*,o.name as organizer_name,o.verified as organizer_verified,r.average_rating,coalesce(r.review_count,0) as review_count,d.name as division_name,di.name as district_name,c.name as category_name,
 case when e.cancelled then 'cancelled' when e.ends_at<=now() then 'completed' when e.starts_at<=now() then 'ongoing' else 'upcoming' end as status,
 public.event_popularity(e.id) as popularity
 from public.events e join public.organizers o on o.id=e.organizer_id join public.divisions d on d.id=e.division_id join public.districts di on di.id=e.district_id join public.categories c on c.id=e.category_id left join public.organizer_ratings r on r.organizer_id=o.id where e.approval='approved' and private.visible_org(o.id);
grant select on public.organizer_ratings,public.organizer_directory,public.event_directory to anon,authenticated;

create function public.update_profile(new_name text) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_user(); update public.profiles set display_name=trim(new_name) where id=auth.uid(); end $$;
create function public.save_organizer(data jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare oid uuid; begin
 perform private.limit_action('organizer',15);
 if exists(select 1 from public.organizers where owner_id=auth.uid() and suspended) then raise exception 'Organizer is suspended' using errcode='42501'; end if;
 insert into public.organizers(owner_id,name,description,contact,website,social_url,logo_path) values(auth.uid(),trim(data->>'name'),data->>'description',data->>'contact',nullif(data->>'website',''),nullif(data->>'social_url',''),nullif(data->>'logo_path',''))
 on conflict(owner_id) do update set name=excluded.name,description=excluded.description,contact=excluded.contact,website=excluded.website,social_url=excluded.social_url,logo_path=excluded.logo_path,approval='pending',verified=false returning id into oid;
 return oid; end $$;
create function public.request_verification(evidence_text text) returns void language plpgsql security definer set search_path='' as $$ declare oid uuid; begin perform private.limit_action('verification',5); select id into oid from public.organizers where owner_id=auth.uid() and not suspended; if oid is null then raise exception 'Organizer profile required'; end if; insert into public.organizer_verifications(organizer_id,user_id,evidence) values(oid,auth.uid(),evidence_text); end $$;
create function public.save_event(data jsonb,event_id uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare oid uuid; eid uuid; begin
 perform private.limit_action('event',30); select id into oid from public.organizers where owner_id=auth.uid() and approval='approved' and not suspended;
 if oid is null then raise exception 'An approved organizer profile is required' using errcode='42501'; end if;
 if event_id is not null and not exists(select 1 from public.events where id=event_id and organizer_id=oid) then raise exception 'Not your event' using errcode='42501'; end if;
 if (data->>'starts_at')::timestamptz<=now() then raise exception 'Event must start in the future'; end if;
 if event_id is null then
 insert into public.events(organizer_id,name,description,category_id,division_id,district_id,starts_at,ends_at,registration_deadline,venue,address,map_url,cover_path,contact,price,registration_url)
 values(oid,trim(data->>'name'),data->>'description',(data->>'category_id')::smallint,(data->>'division_id')::smallint,(data->>'district_id')::smallint,(data->>'starts_at')::timestamptz,(data->>'ends_at')::timestamptz,(data->>'registration_deadline')::timestamptz,data->>'venue',data->>'address',nullif(data->>'map_url',''),nullif(data->>'cover_path',''),data->>'contact',(data->>'price')::numeric,nullif(data->>'registration_url','')) returning id into eid;
 else
 update public.events set name=trim(data->>'name'),description=data->>'description',category_id=(data->>'category_id')::smallint,division_id=(data->>'division_id')::smallint,district_id=(data->>'district_id')::smallint,starts_at=(data->>'starts_at')::timestamptz,ends_at=(data->>'ends_at')::timestamptz,registration_deadline=(data->>'registration_deadline')::timestamptz,venue=data->>'venue',address=data->>'address',map_url=nullif(data->>'map_url',''),cover_path=nullif(data->>'cover_path',''),contact=data->>'contact',price=(data->>'price')::numeric,registration_url=nullif(data->>'registration_url',''),approval='pending',updated_at=now() where id=event_id returning id into eid;
 end if; return eid; end $$;
create function public.cancel_event(eid uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_user(); update public.events set cancelled=true,updated_at=now() where id=eid and private.owns(organizer_id); if not found then raise exception 'Not your event' using errcode='42501'; end if; end $$;
create function public.register_event(eid uuid) returns text language plpgsql security definer set search_path='' as $$ declare e public.events; s text; begin
 perform private.limit_action('registration',60); select * into e from public.events where id=eid for update;
 if not found or not private.visible_event(eid) or e.cancelled or e.registration_deadline<now() or e.starts_at<=now() then raise exception 'Registration is unavailable'; end if;
 s:=case when e.registration_url is null then 'registered' else 'interested' end;
 insert into public.event_registrations(event_id,user_id,status) values(eid,auth.uid(),s) on conflict(event_id,user_id) do update set status=case when public.event_registrations.status='attended' then 'attended' else excluded.status end;
 return s; end $$;
create function public.cancel_registration(eid uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform private.require_user(); update public.event_registrations set status='cancelled' where event_id=eid and user_id=auth.uid() and status<>'attended'; end $$;
create function public.confirm_attendance(registration_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin
 perform private.limit_action('attendance',200); update public.event_registrations r set status='attended' from public.events e where r.id=registration_id and r.event_id=e.id and private.owns(e.organizer_id) and e.ends_at<=now() and not e.cancelled and r.status in ('interested','registered');
 if not found then raise exception 'Attendance can only be confirmed by the organizer after a non-cancelled event'; end if; end $$;
create function public.submit_review(eid uuid,rating integer,review_text text) returns uuid language plpgsql security definer set search_path='' as $$ declare oid uuid; rid uuid; begin
 perform private.limit_action('review',15);
 select e.organizer_id into oid from public.events e join public.event_registrations r on r.event_id=e.id where e.id=eid and r.user_id=auth.uid() and r.status='attended' and e.ends_at<=now() and not e.cancelled and private.visible_event(e.id);
 if oid is null or private.owns(oid) then raise exception 'Verified attendance at a completed event is required; organizers cannot review themselves' using errcode='42501'; end if;
 insert into public.reviews(event_id,user_id,organizer_id,score,body,author_name) values(eid,auth.uid(),oid,rating,review_text,(select display_name from public.profiles where id=auth.uid())) on conflict(event_id,user_id) do update set score=excluded.score,body=excluded.body,moderation='pending',updated_at=now() returning id into rid;
 return rid; end $$;
create function public.reply_review(rid uuid,reply_text text) returns void language plpgsql security definer set search_path='' as $$ begin perform private.limit_action('reply',30); update public.reviews set reply=reply_text where id=rid and private.owns(organizer_id); if not found then raise exception 'Not your organizer review' using errcode='42501'; end if; end $$;
create function public.report_content(kind text,target uuid,reason_text text) returns void language plpgsql security definer set search_path='' as $$ begin perform private.limit_action('report',10); if kind='review' and not exists(select 1 from public.reviews where id=target and moderation='approved') or kind='organizer' and not private.visible_org(target) or kind='event' and not private.visible_event(target) or kind='user' and not exists(select 1 from public.profiles where id=target) then raise exception 'Target not found'; end if; insert into public.reports(user_id,target_type,target_id,reason) values(auth.uid(),kind,target,reason_text); end $$;

create function public.admin_action(action_name text,target uuid,decision text default null) returns void language plpgsql security definer set search_path='' as $$ declare oid uuid; begin
 if not private.admin() then raise exception 'Administrator MFA required' using errcode='42501'; end if;
 case action_name
 when 'organizer' then if decision not in ('approved','rejected') then raise exception 'Invalid decision'; end if; update public.organizers set approval=decision where id=target;
 when 'event' then if decision not in ('approved','rejected') then raise exception 'Invalid decision'; end if; update public.events set approval=decision,updated_at=now() where id=target;
 when 'review' then if decision not in ('approved','rejected') then raise exception 'Invalid decision'; end if; update public.reviews set moderation=decision where id=target;
 when 'verification' then if decision not in ('approved','rejected') then raise exception 'Invalid decision'; end if; update public.organizer_verifications set status=decision where id=target returning organizer_id into oid; update public.organizers set verified=(decision='approved') where id=oid;
 when 'suspend_organizer' then update public.organizers set suspended=true,verified=false where id=target;
 when 'restore_organizer' then update public.organizers set suspended=false where id=target;
 when 'suspend_user' then if target=auth.uid() then raise exception 'Cannot suspend yourself'; end if; update public.profiles set suspended=true where id=target; delete from public.push_tokens where user_id=target;
 when 'restore_user' then update public.profiles set suspended=false where id=target;
 when 'report' then if decision not in ('resolved','dismissed') then raise exception 'Invalid decision'; end if; update public.reports set status=decision where id=target;
 else raise exception 'Unknown administrative action'; end case;
 insert into public.admin_audit_logs(admin_id,action,target_id) values(auth.uid(),action_name||':'||coalesce(decision,''),target);
 end $$;
create function public.admin_reference(kind text,ref_id integer,label text,parent_id integer default null) returns void language plpgsql security definer set search_path='' as $$ begin
 if not private.admin() then raise exception 'Administrator MFA required' using errcode='42501'; end if;
 if kind='category' then if ref_id is null then insert into public.categories(name) values(trim(label)); else update public.categories set name=trim(label) where id=ref_id; end if;
 elsif kind='district' then if ref_id is null then raise exception 'District ID required'; end if; insert into public.districts(id,division_id,name) values(ref_id,parent_id,trim(label)) on conflict(id) do update set name=excluded.name;
 elsif kind='division' then update public.divisions set name=trim(label) where id=ref_id;
 else raise exception 'Unknown reference type'; end if;
 insert into public.admin_audit_logs(admin_id,action) values(auth.uid(),'reference:'||kind||':'||coalesce(ref_id::text,'new'));
 end $$;

create function private.notify_event_change() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if new.approval='approved' and (old.approval<>'approved' or new.cancelled is distinct from old.cancelled or new.starts_at is distinct from old.starts_at) then
 insert into public.notifications(user_id,event_id,title,body) select distinct user_id,new.id,case when new.cancelled then 'Event cancelled' else 'Event update' end,new.name||' has an update. Check the event details.' from (select user_id from public.saved_events where event_id=new.id union select user_id from public.event_registrations where event_id=new.id and status<>'cancelled') audience;
 end if; return new; end $$;
create trigger event_change after update on public.events for each row execute function private.notify_event_change();
create function private.queue_push() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into private.push_outbox(notification_id) values(new.id); return new; end $$;
create trigger notification_push after insert on public.notifications for each row execute function private.queue_push();
create function public.claim_push_batch() returns table(job_id uuid,user_id uuid,title text,body text) language sql security definer set search_path='' as $$
 with picked as (select id from private.push_outbox where delivered_at is null and attempts<5 and (claimed_at is null or claimed_at<now()-interval '10 minutes') order by id limit 50 for update skip locked), claimed as (update private.push_outbox p set claimed_at=now(),attempts=attempts+1 from picked where p.id=picked.id returning p.id,p.notification_id) select c.id,n.user_id,n.title,n.body from claimed c join public.notifications n on n.id=c.notification_id $$;
create function public.finish_push_job(job uuid,error_text text default null) returns void language sql security definer set search_path='' as $$ update private.push_outbox set delivered_at=case when error_text is null then now() else null end,error=left(error_text,300) where id=job $$;
-- Privilege allowlist: do not leave Postgres's default PUBLIC EXECUTE on definer functions.
revoke all on all functions in schema private from public,anon,authenticated;
grant execute on function private.active(),private.admin(),private.owns(uuid),private.visible_org(uuid),private.visible_event(uuid) to anon,authenticated;
revoke all on all functions in schema public from public,anon,authenticated;
grant execute on function public.event_popularity(uuid) to anon,authenticated;
grant execute on function public.update_profile(text),public.save_organizer(jsonb),public.request_verification(text),public.save_event(jsonb,uuid),public.cancel_event(uuid),public.register_event(uuid),public.cancel_registration(uuid),public.confirm_attendance(uuid),public.submit_review(uuid,integer,text),public.reply_review(uuid,text),public.report_content(text,uuid,text),public.admin_action(text,uuid,text),public.admin_reference(text,integer,text,integer) to authenticated;
grant execute on function public.claim_push_batch(),public.finish_push_job(uuid,text) to service_role;
grant select,delete on public.push_tokens to service_role;
